export const ONBOARDING_ASSET_BASE64 = {
  'allow.webp': '',
  'bot-token.webp': '',
  'create-review.webp': '',
  'create-workspace.webp': '',
  'events.webp': '',
  'reinstall.webp': '',
  'signing-secret.webp': '',
} as const;

export type OnboardingAssetName = keyof typeof ONBOARDING_ASSET_BASE64;

export function onboardingAssetBytes(name: string): ArrayBuffer | undefined {
  const encoded = ONBOARDING_ASSET_BASE64[name as OnboardingAssetName];
  if (!encoded) return undefined;
  const decoded = atob(encoded);
  return Uint8Array.from(decoded, (character) => character.charCodeAt(0)).buffer as ArrayBuffer;
}
